import { YAxis as RechartsYAxis, Label } from "recharts";
import { useTheme } from "@theme";

import { YAxisProps } from "../chart.types";
import { useChart } from "../hooks/use-chart";
import { ChartClasses } from "../chart.styles";

const YAxis = (props: YAxisProps) => {
  const theme = useTheme();
  const { handleSort } = useChart();
  const { orientation, sortable, dataKey, label: labelProp, angle = -90, ...rest } = props;

  const label = (
    <Label
      angle={angle}
      className={ChartClasses.yAxisLabel}
      offset={Number(props.offset) || (orientation === "right" ? 18 : 12)}
      position={orientation === "right" ? "insideRight" : "insideLeft"}
      style={{
        cursor: sortable ? "pointer" : undefined,
        fill: theme.color.content.default,
        textAnchor: "middle",
      }}
      value={String(labelProp ?? "")}
      onClick={
        sortable
          ? (e) => {
              e.preventDefault();
              e.stopPropagation();
              handleSort?.(sortable, dataKey as string);
            }
          : undefined
      }
    />
  );

  return (
    <RechartsYAxis
      orientation={orientation}
      stroke={theme.color.border.strong}
      tick={{ fill: theme.color.content.default }}
      tickLine={false}
      {...rest}
      dataKey={dataKey}
      label={label}
    />
  );
};

YAxis.displayName = "YAxis";

export default YAxis;
